import { test, expect } from '@playwright/test';

test.describe('Authentication - Incorrect Password Error', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/login');
  });

  test('should display error message when entering incorrect password', async ({ page }) => {
    // Fill in email field
    await page.getByLabel('Email').fill('user@example.com');

    // Fill in password field with incorrect password
    await page.getByLabel('Password').fill('wrongpassword123');

    // Click login button
    await page.getByRole('button', { name: /login/i }).click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/incorrect password|invalid credentials|authentication failed/i);
    await expect(errorMessage).toBeVisible();
  });

  test('should display error message with specific text for wrong password', async ({ page }) => {
    // Fill in credentials
    await page.getByLabel('Email').fill('testuser@example.com');
    await page.getByLabel('Password').fill('incorrectpass');

    // Submit login form
    await page.getByRole('button', { name: /sign in|login/i }).click();

    // Verify specific error message appears
    const errorAlert = page.getByRole('alert');
    await expect(errorAlert).toContainText(/password|credentials/i);
  });

  test('should clear error message when user modifies password field', async ({ page }) => {
    // Enter incorrect credentials
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('wrongpass');

    // Submit form
    await page.getByRole('button', { name: /login/i }).click();

    // Wait for error message to appear
    const errorMessage = page.getByText(/incorrect password|invalid credentials|authentication failed/i);
    await expect(errorMessage).toBeVisible();

    // Modify password field
    await page.getByLabel('Password').fill('newpassword');

    // Error message should disappear
    await expect(errorMessage).not.toBeVisible();
  });
});
